package com.mvt.backApp.patient.controller;import com.mvt.backApp.common.dto.ApiResponse;import com.mvt.backApp.common.service.ApiResponseFactory;import com.mvt.backApp.patient.dto.*;import com.mvt.backApp.user.service.AuthService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/care-partners/patients") @RequiredArgsConstructor public class CarePartnerPatientController{private final AuthService authService;private final ApiResponseFactory responses;@PostMapping(consumes=MediaType.APPLICATION_JSON_VALUE)@PreAuthorize("hasAuthority(T(com.mvt.backApp.common.security.PermissionNames).CREATE_PATIENT)")public ResponseEntity<ApiResponse<PatientRegistrationResponseDto>> create(@Valid @RequestBody PatientRegistrationDto r){return ResponseEntity.status(201).body(responses.success("success.registration.patientByPartner",201,authService.registerPatientForCurrentPartner(r)));}}
